import ast
from ast import unparse

from .fickle import Interpreter, MarkObject, Opcode, Stack


class Trace:
    def __init__(self, interpreter: Interpreter):
        self.interpreter: Interpreter = interpreter

    def on_pop(self, popped_value: ast.expr | MarkObject):
        value = "MARK" if isinstance(popped_value, MarkObject) else unparse(popped_value).strip()
        print(f"\tPopped {value}")

    def on_push(self, pushed_value: ast.expr | MarkObject):
        value = "MARK" if isinstance(pushed_value, MarkObject) else unparse(pushed_value).strip()
        print(f"\tPushed {value}")

    def on_memoize(self, index: int, value: ast.expr):
        print(f"\tMemoized {index} -> {unparse(value).strip()}")

    def on_update_memo(self, index: int, old_value: ast.expr, new_value: ast.expr):
        print(
            f"\tMemo index {index} changed from {unparse(old_value).strip()} to "
            f"{unparse(new_value).strip()}"
        )

    def on_statement(self, statement: ast.stmt):
        print(f"\t{unparse(statement).strip()}")

    def on_opcode(self, opcode: Opcode):
        print(opcode.name)

    def run(self) -> ast.AST:
        # `Interpreter.run()` validates before stepping, but this drives `step()` itself, so it
        # has to do the same or a frame-straddling pickle would trace as though it were benign.
        self.interpreter.pickled.validate_frames()
        while True:
            memory_before = dict(self.interpreter.memory)
            stack_before = Stack(self.interpreter.stack)
            len_module_before = len(self.interpreter.module_body)
            try:
                opcode = self.interpreter.step()
            except StopIteration:
                break
            self.on_opcode(opcode)
            for added in self.interpreter.module_body[len_module_before:]:
                self.on_statement(added)
            common_prefix_length = 0
            for before, after in zip(stack_before, self.interpreter.stack, strict=False):
                if before != after:
                    break
                common_prefix_length += 1
            for before in reversed(stack_before[common_prefix_length:]):
                self.on_pop(before)
            for after in self.interpreter.stack[common_prefix_length:]:
                self.on_push(after)
            for k, v in self.interpreter.memory.items():
                if k not in memory_before:
                    self.on_memoize(k, v)
                elif v != memory_before[k]:
                    self.on_update_memo(k, memory_before[k], v)
        return self.interpreter.to_ast()

import _pickle
import io
import pickle
import unittest
from pickle import UnpicklingError

import numpy

from fickling import hook
from fickling.exception import UnsafeFileError


# Simple payload for tests
class Payload:
    def __init__(self):
        self.a = 1

    def __reduce__(self):
        import os

        return (os.system, ("echo 'I should have been stopped by the hook'",))


class TestHook(unittest.TestCase):
    def setUp(self):
        # Set up global fickling hook
        hook.run_hook()

    def tearDown(self):
        hook.remove_hook()

    def test_safe_pickle(self):
        # Fickling can check a pickle file for safety prior to running it
        test_list = [1, 2, 3]
        data = pickle.dumps(test_list)
        loaded_data = pickle.load(io.BytesIO(data))
        self.assertEqual(loaded_data, test_list)

    def test_unsafe_pickle(self):
        # Create "unsafe" pickle bytes
        payload = Payload()
        data = pickle.dumps(payload)

        try:
            numpy.load(io.BytesIO(data), allow_pickle=True)
        except UnpicklingError as e:
            if isinstance(e.__cause__, UnsafeFileError):
                pass
            else:
                self.fail(e)

    # https://github.com/trailofbits/fickling/security/advisories/GHSA-wccx-j62j-r448
    # https://github.com/trailofbits/fickling/security/advisories/GHSA-fphw-536r-4p88
    def test_run_hook_covers_all_entry_points(self):
        data = pickle.dumps(Payload())
        cases = {
            "pickle.load": lambda: pickle.load(io.BytesIO(data)),
            "pickle.loads": lambda: pickle.loads(data),
            "pickle.Unpickler": lambda: pickle.Unpickler(io.BytesIO(data)).load(),
            "pickle._load": lambda: pickle._load(io.BytesIO(data)),
            "pickle._loads": lambda: pickle._loads(data),
            "pickle._Unpickler": lambda: pickle._Unpickler(io.BytesIO(data)).load(),
            "_pickle.load": lambda: _pickle.load(io.BytesIO(data)),
            "_pickle.loads": lambda: _pickle.loads(data),
            "_pickle.Unpickler": lambda: _pickle.Unpickler(io.BytesIO(data)).load(),
        }
        for name, call in cases.items():
            with (
                self.subTest(entry_point=name),
                self.assertRaises(UnsafeFileError, msg=f"{name} was not intercepted"),
            ):
                call()

import io
import pickle
import unittest

import numpy
import torch

from fickling import hook
from fickling.exception import UnsafeFileError


# Simple payload for tests
class Payload:
    def __init__(self):
        self.a = 1

    def __reduce__(self):
        import os

        return (os.system, ("echo 'I should have been stopped by the hook'",))


class OuterPayload:
    """Payload to execute arbitrary pickle payload through pickle.loads"""

    def __init__(self, data):
        self.data = data

    def __reduce__(self):
        return (pickle.loads, (self.data,))


class Bypass:
    """Payload to execute arbitrary pickle payload through torch.storage_load_from_bytes"""

    def __init__(self, data):
        self.data = data

    def __reduce__(self):
        return (torch.storage._load_from_bytes, (self.data,))


class TestUnpickler(unittest.TestCase):
    def setUp(self):
        # Create bad pickle bytes before hooking the pickle module because the
        # nested bad file uses the pickle functions.
        self.simple_unsafe_bytes = pickle.dumps(Payload())

        inner = pickle.dumps(Payload())
        self.nested_unsafe_bytes = pickle.dumps(OuterPayload(pickle.dumps(Bypass(inner))))

        inner = pickle.dumps(numpy.dtype(">i4"))
        self.allowed_unsafe_bytes = pickle.dumps(OuterPayload(inner))

        # Set up global fickling hook using unpickler
        hook.activate_safe_ml_environment(also_allow=["pickle.loads", "_pickle.loads"])

    def tearDown(self):
        # Remove fickling hooks
        hook.remove_hook()

    def test_safe_pickle(self):
        # Fickling can check a pickle file for safety prior to running it
        test_list = [1, 2, 3]
        data = pickle.dumps(test_list)
        loaded_data = pickle.load(io.BytesIO(data))
        self.assertEqual(loaded_data, test_list)

    def test_simple_unsafe_pickle(self):
        with self.assertRaises(UnsafeFileError):
            pickle.load(io.BytesIO(self.simple_unsafe_bytes))

    def test_nested_unsafe_pickle(self):
        """This makes sure it catches malicious code in a pickle-inside-pickle situation"""
        with self.assertRaises(UnsafeFileError):
            pickle.load(io.BytesIO(self.nested_unsafe_bytes))

    def test_allowed_unsafe_pickle(self):
        """This checks whether allowing additional imports works in the custom Unpickler"""
        a = pickle.load(io.BytesIO(self.allowed_unsafe_bytes))
        self.assertIsInstance(a, numpy.dtype)
